/*!
 * fv-compat — PasswordStrength (implementación propia sobre zxcvbn, MIT).
 * Opciones: field, message, minimalScore (0-4), onValidated(valid, message, score).
 */
(function (FV) {
    'use strict';
    if (!FV) { return; }
    function PasswordStrength(options) { this.options = Object.assign({minimalScore: 3}, options || {}); }
    PasswordStrength.prototype.install = function (core) {
        var o = this.options, field = o.field;
        if (!field) { return; }
        core.fields[field] = core.fields[field] || {validators: {}};
        core.fields[field].validators = core.fields[field].validators || {};
        core.fields[field].validators.passwordStrength = {message: o.message};
        FV.validators.passwordStrength = FV.validators.passwordStrength || function (input) {
            if (input.value === '') { return {valid: true}; }
            var score = typeof window.zxcvbn === 'function' ? window.zxcvbn(input.value).score : (input.value.length >= 12 ? 3 : 1);
            var valid = score >= o.minimalScore;
            if (typeof o.onValidated === 'function') { o.onValidated(valid, o.message, score); }
            return {valid: valid, message: o.message};
        };
    };
    FV.plugins.PasswordStrength = PasswordStrength;
})(window.FormValidation);
